#include <stdio.h>
#include <string.h>
#include <assert.h>

int fixedpoint_d2string(char *dst, size_t dstlen, double dvalue, int fractional_digits);

static void t(double v, int fd, const char *expect) {
    char buf[64];
    memset(buf, '\xff', sizeof buf); /* prefill with garbage, like a reused buffer */
    int sz = fixedpoint_d2string(buf, sizeof buf, v, fd);
    printf("v=%-10g fd=%-2d -> sz=%d '%s'", v, fd, sz, buf);
    if (sz != (int)strlen(expect) || strcmp(buf, expect) != 0) {
        printf("  FAIL (expected '%s' len %zu)\n", expect, strlen(expect));
        fails++;
    } else {
        printf("  ok\n");
    }
}

int fails = 0;
int main(void) {
    /* existing cases */
    t(0.0, 4, "0.0000");
    t(0.0, 1, "0.0");
    t(0.01, 4, "0.0100");
    t(0.01, 1, "0.0");
    t(-0.01, 4, "-0.0100");
    t(-0.1, 1, "-0.1");
    t(0.1, 1, "0.1");
    t(0.01, 17, "0.01000000000000000");
    t(10.01, 4, "10.0100");
    /* leading fractional zero cases (the GEORADIUS bug) */
    t(0.0001, 4, "0.0001");
    t(0.001, 4, "0.0010");
    t(0.00001, 4, "0.0000");
    t(0.0012, 4, "0.0012");
    t(0.5, 4, "0.5000");
    t(1.0, 4, "1.0000");
    t(12.3456, 4, "12.3456");
    t(123.4567, 4, "123.4567");
    t(1.2, 3, "1.200");
    t(0.0012, 3, "0.001");
    t(100.0, 4, "100.0000");
    t(-0.0001, 4, "-0.0001");
    if (fails) { printf("%d FAILURES\n", fails); return 1; }
    printf("all ok\n");
    return 0;
}

